def __class_getitem__(cls, item):
    new_cls = type(cls.__name__, (cls,), {'_data_type': item})
    return new_cls

def load_variable_values(self, var_name):
    for scope in reversed(self.scopes):
        if var_name in scope:
            return scope[var_name]
    return None

def visit_Assign(self, node):
    target = node.targets[0]
    value = node.value
    if isinstance(target, ast.Name):
        if isinstance(value, ast.List):
            self.scopes[-1][target.id] = [self.get_value(elt) for elt in value.elts]
        elif isinstance(value, ast.Name):
            self.scopes[-1][target.id] = self.load_variable_values(value.id)
        else:
            self.scopes[-1][target.id] = self.get_value(value)

def get_value(self, node):
    if isinstance(node, ast.Str):
        return node.s
    elif isinstance(node, ast.Num):
        return node.n
    elif isinstance(node, ast.NameConstant):
        return node.value
    elif isinstance(node, ast.List):
        return [self.get_value(e) for e in node.elts]
    elif isinstance(node, ast.Dict):
        keys = [self.get_value(k) for k in node.keys]
        values = [self.get_value(v) for v in node.values]
        return dict(zip(keys, values))
    elif isinstance(node, ast.Name):
        value = self.load_variable_values(node.id)
        # check if value has a __dict__ attribute
        if hasattr(value, "__dict__"):
            return value.__dict__
        else:
            return value
    elif isinstance(node, ast.Call):
        return self.extract_output(node)
    else:
        # This is a simplification; you might want to add more types
        raise NotImplementedError(f"Node type {type(node)} not supported")

def instantiate(self, func, *args, **kwargs):
    """Instantiate a function with the given arguments and keyword arguments."""
    try:
        return func(*args, **kwargs)
    except TypeError as e:
        # If the function cannot be instantiated, return the function itself
        return func
    except Exception as e:
        raise e

def extract_output(self, node, scope=None):
    # current_scope = self.scopes[-1]

    def eval_args(args, scope):
        return [self.extract_output(arg, scope) for arg in args]

    def eval_kwargs(keywords, scope):
        return {kw.arg: self.extract_output(kw.value, scope) for kw in keywords}

    if isinstance(node, ast.Num):
        return node.n
    elif isinstance(node, ast.Str):
        return node.s
    elif isinstance(node, ast.List):
        return [self.extract_output(elt, scope) for elt in node.elts]
    elif isinstance(node, ast.Dict):
        return {self.extract_output(k, scope): self.extract_output(v, scope) for k, v in
                zip(node.keys, node.values)}
    elif isinstance(node, ast.Name):
        return self.load_variable_values(node.id)
    elif isinstance(node, ast.Call):
        if isinstance(node.func, ast.Name):
            func_name = node.func.id
            args = eval_args(node.args, scope)
            kwargs = eval_kwargs(node.keywords, scope)

            # if func_name == "TodoItem":
            #     return TodoItem(*args, **kwargs)
            # elif func_name == "datetime":
            #     return datetime.datetime(*args, **kwargs)
            _globals = globals()
            _function_globals = self.local_scope[self.wrapper_alias].__globals__ if self.wrapper_alias in self.local_scope else {}
            # Generalized object instantiation
            if func_name in self.imported_modules:
                module = self.imported_modules[func_name]
                if hasattr(module, func_name):
                    func = getattr(module, func_name)
                    return self.instantiate(func, *args, **kwargs)

            elif func_name in _globals:
                func = _globals[func_name]
                return self.instantiate(func, *args, **kwargs)
            elif func_name in self.local_scope:
                func = self.local_scope[func_name]
                return self.instantiate(func, *args, **kwargs)
            elif func_name in _function_globals:
                func = _function_globals[func_name]
                return self.instantiate(func, *args, **kwargs)
            else:
                raise NotImplementedError(f"Function {func_name} not handled yet")
        elif isinstance(node.func, ast.Attribute):
            func_name = node.func.attr
            # obj = self.extract_output(node.func.value, scope)
            _globals = globals()
            _function_globals = self.local_scope[self.wrapper_alias].__globals__ if self.wrapper_alias in self.local_scope else {}
            if isinstance(node.func.value, ast.Name):
                module_or_class_name = node.func.value.id

                if module_or_class_name == 'self':
                    # Handling methods called on 'self'
                    args = eval_args(node.args, scope)
                    kwargs = eval_kwargs(node.keywords, scope)
                    patched_func_scope = self.patch_symbolic_funcs[func_name]
                    #method = getattr(scope['self'], func_name, None)
                    if patched_func_scope:
                        return self.instantiate(patched_func_scope, *args, **kwargs)
                    else:
                        raise NotImplementedError(f"Method {func_name} not found in class")

                # Check if module_or_class_name is an imported module
                if module_or_class_name in self.imported_modules:
                    obj = self.imported_modules[module_or_class_name]
                # Check if module_or_class_name is a globally defined class
                elif module_or_class_name in _globals:
                    obj = _globals[module_or_class_name]
                elif module_or_class_name in builtins.__dict__:
                    obj = builtins.__dict__[module_or_class_name]
                elif module_or_class_name in self.local_scope:
                    obj = self.local_scope[module_or_class_name]
                elif module_or_class_name in _function_globals:
                    obj = _function_globals[module_or_class_name]
                else:
                    raise NotImplementedError(f"Module or class {module_or_class_name} not found")
            else:
                obj = self.extract_output(node.func.value, scope)
            args = eval_args(node.args, scope)
            kwargs = eval_kwargs(node.keywords, scope)

            if hasattr(obj, func_name):
                func = getattr(obj, func_name)
                return self.instantiate(func, *args, **kwargs)
            else:
                raise NotImplementedError(f"Attribute-based call {obj}.{func_name} not handled yet")

        # Add additional function handling here
    elif isinstance(node, ast.Attribute):
        # Handle attributes like datetime.datetime
        obj = self.extract_output(node.value, scope)
        return getattr(obj, node.attr)
    elif isinstance(node, ast.Tuple):
        return tuple(self.extract_output(elt, scope) for elt in node.elts)
    elif isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.USub):
            return -self.extract_output(node.operand, scope)
        elif isinstance(node.op, ast.Not):
            return not self.extract_output(node.operand, scope)
        else:
            raise NotImplementedError(f"Unary operator {type(node.op).__name__} not handled yet")
    raise NotImplementedError(f"Node type {type(node).__name__} not handled yet")

def extract_variable_name(self, node):
    if isinstance(node, ast.Name):
        return node.id
    elif isinstance(node, ast.Call):
        if isinstance(node.func, ast.Name):
            return node.func.id  # For now, just return the function name. You may also traverse args.
    return None  # Or raise an exception depending on your need

def visit_Import(self, node):
    for name in node.names:
        self.imported_modules[name.name.split('.')[0]] = __import__(name.name)

def visit_ImportFrom(self, node):
    module_name = node.module
    self.imported_modules[module_name.split('.')[0]] = __import__(module_name)

def visit_Assert(self, node):
    # Check if either side of the assert involves a patched function
    left_func_name = self.extract_func_name(node.test.left) if isinstance(node.test.left, ast.Call) else None
    right_func_name = self.extract_func_name(node.test.comparators[0]) if isinstance(node.test.comparators[0],
                                                                                     ast.Call) else None

    left_is_patchable = self.is_function_patchable(left_func_name, self.instance) if left_func_name else False
    right_is_patchable = self.is_function_patchable(right_func_name,
                                                    self.instance) if right_func_name else False

    # Proceed only if at least one side is a patched function call
    if left_is_patchable or right_is_patchable:
        if isinstance(node.test.ops[0], ast.Eq):
            return self.create_register_call(node, _align_direction=True)
        elif isinstance(node.test.ops[0], ast.NotEq):
            return self.create_register_call(node, _align_direction=False)
        else:
            return node  # Non-supported comparison operator
    else:
        return node  # Neither side involves a patched function

def transform_arg(self, node):
    """
    Transforms an AST node into a form suitable for inclusion in the args list of an ast.Call node.
    """
    if isinstance(node, ast.Str):
        return node  # Strings can be directly included
    elif isinstance(node, ast.Num):
        return node  # Numbers can be directly included
    elif isinstance(node, ast.Name):
        return ast.Name(id=node.id, ctx=ast.Load())  # Variables are included by name
    elif isinstance(node, (ast.List, ast.Dict, ast.Tuple)):
        return node  # Directly include compound types
    elif isinstance(node, ast.Constant):
        return node
    else:
        return node
        #raise NotImplementedError(f"Unsupported argument type: {type(node)}")

def process_assert(self, node, iter_name=None, evaluated_expr=None):

    if isinstance(node.test, ast.UnaryOp) and isinstance(node.test.op, ast.Not):
        # Special case for 'assert not ...'. We have to convert it into 'assert ... == None'
        operand = node.test.operand
        self.process_assert_helper(operand, ast.NameConstant(value=None), iter_name, op=ast.Eq())
        return

    left = node.test.left
    right = node.test.comparators[0]

    if iter_name:
        for input_val in evaluated_expr:
            self.scopes.append({iter_name: input_val})
            self.process_assert_helper(left, right, iter_name, op=node.test.ops[0])
            self.scopes.pop()
    else:
        self.process_assert_helper(left, right, op=node.test.ops[0])

def process_assert_with_tuple(self, node, iter_names, evaluated_expr):
    left = node.test.left
    right = node.test.comparators[0]

    if isinstance(node.test.ops[0], (NotEq, NotIn, IsNot)):
        return

    if evaluated_expr is not None:
        # Loop through the evaluated expression (which should be an iterable)
        for input_tuple in evaluated_expr:
            # Create a new scope for these variables
            self.scopes.append(dict(zip(iter_names, input_tuple)))

            if isinstance(node.test, ast.UnaryOp) and isinstance(node.test.op, ast.Not):
                # Special case for 'assert not ...'
                #operand = node.test.operand
                self.process_assert_helper(left, ast.NameConstant(value=None), op=ast.Eq())
            else:
                # Process the assert statement
                self.process_assert_helper(left, right, op=node.test.ops[0])

            # Remove the temporary scope
            self.scopes.pop()

def process_assert_helper(self, left, right, iter_name=None, op=None):
    """
    This is a helper function for processing asserts. It is low-level and is called by higher-level functions
    that analyze the AST of the aligned function.

    It handles the case where both sides of the assert statement are patched embedding functions: where we need to
    do special mocking.

    It also handles the case where the left side of the assert statement is a patched symbolic function.

    Args:
        left: The expression on the left of an assert statement
        right: The expression on the right of an assert statement
        iter_name: The name of the iterator variable (if any)
        op: The operator used in the assert statement (e.g. ast.Eq() for '==')
    """
    if self.is_embeddable_function_call(left) and self.is_embeddable_function_call(right):
        # Both sides are patched embeddable functions
        self.process_assert_helper_both_sides_embeddable(left, right, iter_name, op)
    elif self.is_embeddable_function_call(left) and not self.is_embeddable_function_call(right):
        raise ValueError("Cannot compare patched embeddable function with non-patched embeddable function")
    elif not self.is_embeddable_function_call(left) and self.is_embeddable_function_call(right):
        raise ValueError("Cannot compare non-patched embeddable function with patched embeddable function")
    else:
        # Only equality operators make sense when dealing with symbolic functions.
        # e.g Telling an LLM that a function should not yield X is not meaningful
        # (as the set of possible outputs is infinite)
        if isinstance(op, (NotEq, NotIn, IsNot)):
            return

        if isinstance(left, ast.Call):
            if isinstance(left.func, ast.Name) and left.func.id in self.patch_symbolic_names:
                self.process_assert_helper_lr(left, right, iter_name, op)
            elif isinstance(left.func, ast.Attribute) and left.func.attr in self.patch_symbolic_names:
                self.process_assert_helper_lr(left, right, iter_name, op)
            else:
                if isinstance(right.func, ast.Name) and right.func.id in self.patch_symbolic_names:
                    self.process_assert_helper_lr(right, left, iter_name, op)
                elif isinstance(right.func, ast.Attribute) and right.func.attr in self.patch_symbolic_names:
                    self.process_assert_helper_lr(right, left, iter_name, op)

        elif isinstance(right, ast.Call):
            if isinstance(right.func, ast.Name) and right.func.id in self.patch_symbolic_names:
                self.process_assert_helper_lr(right, left, iter_name, op)
            elif isinstance(right.func, ast.Attribute) and right.func.attr in self.patch_symbolic_names:
                self.process_assert_helper_lr(right, left, iter_name, op)

def process_assert_helper_both_sides_embeddable(self, left, right, iter_name=None, op=None):

    if hasattr(left.func, 'attr') and hasattr(right.func, 'attr') and left.func.attr != right.func.attr:
        raise ValueError(f"Cannot compare two different patched embeddable functions: {left} and {right}")
    if hasattr(left.func, 'id') and hasattr(right.func, 'id') and left.func.id != right.func.id:
        raise ValueError(f"Cannot compare two different patched embeddable functions: {left} and {right}")

    left_args, left_kwargs = self.extract_args(left, iter_name)
    right_args, right_kwargs = self.extract_args(right, iter_name)

    left_key = get_key(left_args, left_kwargs)
    right_key = get_key(right_args, right_kwargs)

    if isinstance(op, ast.Eq):
        # For equality, both sides should produce the same mock value
        if left_key in self.mocks:
            self.mocks[right_key] = self.mocks[left_key]
        elif right_key in self.mocks:
            self.mocks[left_key] = self.mocks[right_key]
        else:
            mock_value = self.generate_mock_embedding()
            self.mocks[left_key] = mock_value
            self.mocks[right_key] = mock_value
    elif isinstance(op, ast.NotEq):
        # For inequality, ensure different mock values
        if left_key in self.mocks:
            self.mocks[right_key] = self.generate_mock_embedding()
        elif right_key in self.mocks:
            self.mocks[left_key] = self.generate_mock_embedding()
        else:
            self.mocks[left_key] = self.generate_mock_embedding()
            self.mocks[right_key] = self.generate_mock_embedding()

        self.negative_mocks[left_key] = right_key

def generate_mock_embedding(self):
    # Method to generate a unique mock value
    return f"MockEmbedding_{uuid.uuid4()}"

def is_embeddable_function_call(self, node):
    # Helper method to determine if a node is a call to a patched function
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Name) and node.func.id in self.patch_embeddable_funcs:
            return True
        elif isinstance(node.func, ast.Attribute) and node.func.attr in self.patch_embeddable_funcs:
            return True
    return False

def process_assert_helper_lr(self, left, right, iter_name=None, op=None):
    input_args, input_kwargs = self.extract_args(left, iter_name)
    if isinstance(op, In):
        output = Or(self.extract_output(right))
    else:
        output = self.extract_output(right)

    key = get_key(input_args, input_kwargs)

    self.mocks[key] = output

def extract_args(self, node, iter_name=None):
    # Assuming all arguments are positional
    args = []
    current_scope = self.scopes[-1]
    for arg in node.args:
        value = self.eval_expr(arg)
        if callable(value):
            if iter_name is not None:
                arg_values = [current_scope.get(arg_name, None) for arg_name in iter_name]
                value = value(*arg_values)
            else:
                value = value()
        elif value is None:
            # If evaluation returns None, fall back to scope
            value = current_scope.get(arg.id, None)
        args.append(value)

    # Extract keyword arguments
    kwargs = {}
    for kw in node.keywords:
        kw_value = self.eval_expr(kw.value)
        if callable(kw_value):
            if iter_name is not None:
                kw_values = [current_scope.get(arg_name, None) for arg_name in iter_name]
                kw_value = kw_value(*kw_values)
            else:
                kw_value = kw_value()
        elif kw_value is None:
            # If evaluation returns None, fall back to scope
            kw_value = current_scope.get(kw.arg, None)
        kwargs[kw.arg] = kw_value

    return args, kwargs

def eval_expr(self, node):
    current_scope = self.scopes[-1]
    if isinstance(node, ast.Name):
        # Prioritize variables in the current scope over built-in functions
        if node.id in current_scope:
            return current_scope[node.id]
        elif hasattr(builtins, node.id):
            func = getattr(builtins, node.id)
            return func

    elif isinstance(node, ast.Call):
        # Function call, could be 'zip' or other
        func = self.eval_expr(node.func)  # Recursively evaluate the function expression
        if func is None:
            raise ValueError(
                f"Function {node.func.id if isinstance(node.func, ast.Name) else ''} not found in the current scope or built-ins.")

        args = [self.eval_expr(arg) for arg in node.args]  # Recursively evaluate the arguments
        return func(*args)  # Assume func_name is a Python built-in, e.g., zip
    elif isinstance(node, ast.Num):
        return node.n  # Assume it's a number for simplicity
    elif isinstance(node, ast.Str):
        return node.s  # Assume it's a string for simplicity
    elif isinstance(node, ast.List):
        return [self.eval_expr(x) for x in node.elts]  # Assume it's a list for simplicity
    elif isinstance(node, ast.Tuple):
        return tuple([self.eval_expr(x) for x in node.elts])  # Assume it's a tuple for simplicity
    elif isinstance(node, ast.Dict):
        return {self.eval_expr(k): self.eval_expr(v) for k, v in zip(node.keys, node.values)}
    else:
        raise NotImplementedError(f"Node type {type(node).__name__} not handled yet")

def visit_For(self, node):
    if isinstance(node.target, ast.Name):
        evaluated_expr = self.eval_expr(node.iter)
        iter_name = node.target.id
        if iter_name:
            for stmt in node.body:
                if isinstance(stmt, ast.Assert):
                    self.process_assert(stmt, iter_name, evaluated_expr)
    # If loop variable is a tuple
    elif isinstance(node.target, ast.Tuple):
        iter_names = [elt.id for elt in node.target.elts]  # Extract names from tuple
        # iter_name = self.extract_variable_name(node.iter)
        evaluated_expr = self.eval_expr(node.iter)
        for stmt in node.body:
            if isinstance(stmt, ast.Assert):
                self.process_assert_with_tuple(stmt, iter_names, evaluated_expr)

    self.scopes.pop()

def validate_output(self, output: str, type_definition: Any) -> bool:
    try:
        deserialized_output = json.loads(output)
    except json.JSONDecodeError:
        return False

    return self.check_type(deserialized_output, type_definition)

def _deep_tuple(obj):
    """
    Convert a list or dict to a tuple recursively to allow for hashing and becoming a key for mock_behaviors
    :param obj:
    :return:
    """
    # transform pydantic objects into dicts
    if hasattr(obj, "__dict__"):
        obj = obj.__dict__
    if isinstance(obj, list) or isinstance(obj, tuple):
        return tuple(_deep_tuple(e) for e in obj)
    elif isinstance(obj, dict):
        return tuple((k, _deep_tuple(v)) for k, v in sorted(obj.items()))
    else:
        return obj

def is_base_type(self, _type: Any) -> bool:
    """Determine if a type is a base type."""
    return _type in {int, float, str, bool, None}

def validate_base_type(self, value: Any, typ: Any) -> bool:
    """Validate base types."""
    if typ is None:
        return value is None
    return isinstance(value, typ)

def check_type(self, value: Any, type_definition: Any) -> bool:
    """
    Validate a value against a type definition.

    Args:
        value: Any object or primitive value
        type_definition: The type definition to validate against

    Returns:
        Whether the value is valid for the type definition
    """
    if type_definition is Any:
        return True

    if self.is_base_type(type_definition):
        return self.validate_base_type(value, type_definition)

    origin = get_origin(type_definition) or type_definition
    args = get_args(type_definition)

    # Handle base types
    if self.is_base_type(origin):
        return self.validate_base_type(value, origin)

    if origin == Literal:
        return value in args

    if origin == Union:
        return any(self.check_type(value, union_type) for union_type in args)

    # Handle tuples
    if origin == tuple:
        if not isinstance(value, tuple):
            return False
        item_type = args[0] if args else Any
        return all(self.check_type(v, item_type) for v in value)

    # Handle lists
    if origin == list:
        if not isinstance(value, list):
            return False
        item_type = args[0] if args else Any
        return all(self.check_type(v, item_type) for v in value)

    # Handle more complex types that are collections and list-like
    if origin is list or issubclass(origin, tuple(self.list_like_types)):
        if not any(isinstance(value, t) for t in self.list_like_types):
            return False
        item_type = args[0] if args else Any
        return all(self.check_type(v, item_type) for v in value)

    # Handle sets
    if origin == set:
        if not isinstance(value, set):
            return False
        item_type = args[0] if args else Any
        return all(self.check_type(v, item_type) for v in value)

    # Handle datetime
    if origin in [datetime.datetime, datetime.date, datetime.time]:
        # try to instantiate datetime
        try:
            obj = origin(**value)
            return True
        except:
            return False
    # Handle dictionaries
    if origin is dict or issubclass(origin, tuple(self.dict_like_types)):
        if not isinstance(value, (dict, Mapping)):#, MutableMapping, OrderedDict)):
            return False

        if args:
            if len(args) == 1:
                key_type = args[0]
                value_type = Any  # General assumption; specific dict-like types might differ
            elif len(args) == 2:
                key_type, value_type = args
            else:
                key_type = value_type = Any
        else:
            key_type = value_type = Any

        return all(
            self.check_type(k, key_type) and self.check_type(v, value_type)
            for k, v in value.items()
        )

    # Handle pydantic models
    if self.is_pydantic_model(origin):
        try:
            #temp_model = create_model('TempModel', **value)
            if isinstance(value, origin):
                return True
            #return isinstance(temp_model, origin)
            # check if value is dict
            if not isinstance(value, dict):
                return False
            # get all required init arguments for origin
            # required arguments are the ones withouyt default values
            required_fields = [field for field, field_type in origin.__annotations__.items() if not (typing.get_origin(field_type) is Union and type(None) in typing.get_args(field_type))]
            # check that all required arguments are in value and do type checking
            for arg in required_fields:
                # check if it is in value
                if arg not in value:
                    return False
                # get the type of the argument
                arg_type = origin.__annotations__[arg]
                if not self.check_type(value[arg], arg_type):
                    return False
            # check that all arguments in value are correct type
            # this is additional check, because the above check only checks required arguments
            for arg, obj in value.items():
                if arg in required_fields:
                    continue
                arg_type = origin.__annotations__[arg]
                if not self.check_type(value[arg], arg_type):
                    return False

            #origin.parse_obj(value)
            return True
        except Exception as e:
            print(e)
            return False

    # Handle dataclasses
    if self.is_dataclass_instance(origin):
        try:
            # for field in dataclasses.fields(origin):
            #     field_name = field.name
            #     field_type = field.type
            #     if field_name not in value or not self.check_type(value[field_name], field_type):
            #         return False
            # return True
            obj = origin(**value)
            return dataclasses.asdict(obj) == value
        except:
            return False

    # Handle dataclasses and arbitrary class types
    if inspect.isclass(origin) and not self.is_base_type(origin):
        # Ensure the value is an instance of the class
        if not isinstance(value, origin):
            return False

        # Gather type hints from the class and its bases
        type_hints = {}
        for cls in reversed(origin.__mro__):
            type_hints.update(get_type_hints(cls))

        # Validate each attribute of the class
        for attr, attr_type in type_hints.items():
            attr_value = getattr(value, attr, None)
            if not self.check_type(attr_value, attr_type):
                return False

        return True

    return False

def _is_subclass_of_generic(cls: Type, generic: Type) -> bool:
    """Determine if the class is a subclass of a generic type."""
    try:
        return issubclass(cls, generic) and cls is not generic
    except TypeError:
        if not hasattr(cls, '__origin__'):
            return False
    return cls.__origin__ is generic

def _is_generic(cls: Type) -> bool:
    """Check if the provided type is a generic."""
    return hasattr(cls, "__origin__")

def _get_recursive_args(self, target_type: Type) -> Tuple[Type, ...]:
    """
    Recursively check the base classes (i.e., the superclass chain) of the target type until we find one that
    retains the type arguments.
    :return: Type chain
    """
    if get_args(target_type):
        return get_args(target_type)
    for base in target_type.__bases__:
        args = self._get_recursive_args(base)
        if args:
            return args
    return ()

def _find_generic_base_and_args(self, target_type: Type) -> Tuple[Type, Tuple[Type, ...]]:
    """
    Navigate up the MRO to find the first generic base and its arguments.
    """
    # First, check if target_type is a type annotation.
    # If so, directly return its origin and arguments.
    origin = get_origin(target_type)
    args = get_args(target_type)
    if origin and args:
        return origin, args

    # If target_type is a real class, then navigate its MRO.
    if hasattr(target_type, '__mro__'):
        if hasattr(target_type, '__orig_bases__'):
            for base in target_type.__orig_bases__:
                if get_args(base):
                    return base, get_args(base)

        for base in target_type.__mro__:
            if get_args(base):
                return base, get_args(base)

    return None, ()

def _is_list_like(self, target_type: Type) -> bool:
    """Determine if the target type is list-like."""
    if target_type in {list, typing.List}:
        return True
    if hasattr(target_type, "__origin__") and target_type.__origin__ in {list, typing.List}:
        return True
    return False

def _is_tuple_like(self, target_type: Type) -> bool:
    """Determine if the target type is tuple-like."""
    if target_type in {tuple, typing.Tuple}:
        return True
    if hasattr(target_type, "__origin__") and target_type.__origin__ in {tuple, typing.Tuple}:
        return True
    return False

def _is_dict_like(self, target_type: Type) -> bool:
    """Determine if the target type is dict-like."""
    if target_type in {dict, typing.Dict}:
        return True
    if hasattr(target_type, "__origin__") and target_type.__origin__ in {dict, typing.Dict}:
        return True
    return False

def _is_set_like(self, target_type: Type) -> bool:
    """Determine if the target type is set-like."""
    if target_type in {set, typing.Set}:
        return True
    if hasattr(target_type, "__origin__") and target_type.__origin__ in {set, typing.Set}:
        return True
    return False

def instantiate(self, data: Any, target_type: Type) -> Any:
    """
    Attempts to convert a JSON-compatible data structure into an instance of the specified type.

    Args:
        data: JSON-compatible data structure to instantiate the target type.
        target_type: The type to instantiate from the given data.

    Returns:
        An instance of the target type initialized with the data.
    """

    # Handle None type
    if data is None:
        return None

    origin = get_origin(target_type) or target_type

    # If the target type is a built-in, attempt to instantiate and return
    if self.is_base_type(target_type) or target_type is Any:
        # If the parsed data is a string and target type is str, return it directly
        if isinstance(data, str) and target_type is str:
            return data

        # If any, return the data directly
        if target_type is Any:
            return data

        try:
            return target_type(data)
        except (ValueError, TypeError):
            # Handle the special case where the string represents a float but we want an integer
            if target_type is int:
                try:
                    return int(float(data))
                except (ValueError, TypeError):
                    pass

            if target_type is float:
                try:
                    return int(float(data))
                except (ValueError, TypeError):
                    pass
            raise TypeError(f"Failed to instantiate {target_type} from provided data.")
    # special handling for datetime
    if origin == datetime.datetime:
        # try to instantiate datetime
        try:
            return datetime.datetime(**data)
        except:
            raise TypeError(f"Failed to instantiate {target_type} from provided data.")

    # check if origin is Union, if so, instantiate the first type that works
    if origin == Union:
        for arg in get_args(target_type):
            try:
                return self.instantiate(data, arg)
            except:
                continue
        raise TypeError(f"Failed to instantiate {target_type} from provided data.")

    # If the data is a dictionary and the target is a custom class that can be instantiated from a dictionary.
    if isinstance(data, dict):
        if inspect.isclass(target_type) and not self.is_base_type(target_type):
            # Special handling for dataclasses
            if is_dataclass(target_type):
                fields = [f.name for f in dataclasses.fields(target_type)]
                type_hints = get_type_hints(target_type)
                filtered_data = {k: self.instantiate(v, type_hints.get(k, Any)) for k, v in data.items() if
                                 k in fields}
                return target_type(**filtered_data)

            # Special handling for Pydantic models
            if issubclass(target_type, BaseModel):
                # instantiate the sub attributes
                for attr, attr_type in target_type.__annotations__.items():
                    if attr in data:
                        data[attr] = self.instantiate(data[attr], attr_type)
                try:
                    return target_type.model_validate(data)
                except AttributeError as e:
                    # backwards compatibility with pydantic < 2
                    return target_type.parse_obj(data)


            # For general classes, attempt instantiation
            try:
                return target_type(**data)
            except TypeError:
                raise TypeError(f"Failed to instantiate {target_type.__name__} from dictionary.")
        # Handle dictionary-like types
        # Check if the target type is or inherits from defaultdict
        if origin is defaultdict or (isinstance(origin, type) and issubclass(origin, defaultdict)):
            key_type, value_type = get_args(target_type) if get_args(target_type) else (Any, Any)
            instantiated_items = {self.instantiate(k, key_type): self.instantiate(v, value_type) for k, v in
                                  data.items()}

            # For defaultdict, you'll need a default factory. Here, I'm using `int` for simplicity,
            # but you might want to adapt this based on your needs.
            return defaultdict(int, instantiated_items)

        # Handle set-like dict types like OrderedDict
        # the first check needs to be done to ensure origin has the __mro__ attribute
        elif inspect.isclass(origin)and any(issubclass(base, dict) for base in origin.__mro__):
            key_type, value_type = get_args(target_type) if get_args(target_type) else (Any, Any)
            instantiated_items = {self.instantiate(k, key_type): self.instantiate(v, value_type) for k, v in data.items()}
            return origin(instantiated_items)

        # Handle other dictionary-like types
        elif origin is dict or self._is_subclass_of_generic(origin, dict):
            key_type, value_type = get_args(target_type) if get_args(target_type) else (Any, Any)
            instantiated_dict = {self.instantiate(k, key_type): self.instantiate(v, value_type) for k, v in
                                 data.items()}

            # If the target_type is a subclass of dict, return an instance of target_type
            if self._is_subclass_of_generic(target_type, dict) and not self._is_generic(target_type):
                return target_type(instantiated_dict)
            else:
                return dict(instantiated_dict)

    # Tuples aren't supported in JSONable types, so we look for lists instead
    if isinstance(data, list):
        try:
            # If the origin or target type is a list-like type, or if it implements a list-like collections type
            # e.g Sequence[int]
            if origin is list or self._is_subclass_of_generic(origin, list):
                base, item_types = self._find_generic_base_and_args(target_type)

                item_type = item_types[0] if item_types else Any

                instantiated_items = []

                for item in data:
                    # For each item, validate and instantiate it
                    try:
                        instantiated_item = self.instantiate(item, item_type)
                    except ValueError:
                        raise TypeError(
                            f"Item of type {type(item).__name__} does not match expected type {item_type[0].__name__}.")

                    safe = self.check_type(instantiated_item, item_type)
                    if not safe:
                        raise TypeError(
                            f"Item of type {type(item).__name__} does not match expected type {item_type[0].__name__}.")
                    instantiated_items.append(instantiated_item)

                # If target_type is a subclass of list, return an instance of target_type
                if self._is_subclass_of_generic(target_type, list) and not self._is_generic(target_type):
                    return target_type(instantiated_items)

                return instantiated_items

            # Handle tuples
            if self._is_tuple_like(target_type) or (isinstance(origin, type) and issubclass(origin, tuple)):
                base, item_types = self._find_generic_base_and_args(target_type)

                instantiated_items = []

                # If there are no subscripted types, assume Any
                if not item_types:
                    item_types = (Any,) * len(data)

                for i, item in enumerate(data):
                    # For each item, validate and instantiate it
                    instantiated_item = self.instantiate(item, item_types[i])
                    instantiated_items.append(instantiated_item)

                    # If the instantiated item does not match the expected type, raise an exception
                    _type = item_types[i]
                    if not isinstance(instantiated_item, _type):
                        raise TypeError(
                            f"Item {i} of type {type(item).__name__} does not match expected type {item_types[i].__name__}.")

                # Convert the list of instantiated items to a tuple
                instantiated_tuple = tuple(instantiated_items)
                # If target_type is a subclass of tuple, return an instance of target_type
                if self._is_subclass_of_generic(target_type, tuple):
                    return target_type(instantiated_tuple)

                return instantiated_tuple

            # Handle sets
            if self._is_set_like(target_type) or (isinstance(origin, type) and issubclass(origin, set)):
                base, item_type = self._find_generic_base_and_args(target_type)

                if not item_type:
                    item_type = Any

                instantiated_items = set()

                for item in data:
                    # For each item, validate and instantiate it
                    instantiated_item = self.instantiate(item, item_type[0])
                    instantiated_items.add(instantiated_item)

                    # If the instantiated item does not match the expected type, raise an exception
                    if not isinstance(instantiated_item, item_type[0]):
                        raise TypeError(
                            f"Item of type {type(item).__name__} does not match expected type {item_type[0].__name__}.")

                # If target_type is a subclass of set, return an instance of target_type
                if self._is_subclass_of_generic(target_type, set):
                    return target_type(instantiated_items)

                return instantiated_items

            # Handle deques
            if origin is deque or (isinstance(origin, type) and issubclass(origin, set)):
               item_type = get_args(target_type)[0] if get_args(target_type) else Any
               return deque(self.instantiate(item, item_type) for item in data)

            if origin is frozenset or (isinstance(origin, type) and issubclass(origin, frozenset)):
               item_type = get_args(target_type)[0] if get_args(target_type) else Any
               return frozenset(self.instantiate(item, item_type) for item in data)

        except TypeError as e:
            print(e)
            raise TypeError(f"Failed to instantiate {target_type} from list. {e}")

    # If none of the above, return the data as-is
    return data

def is_function_patchable(self, func_name, instance=None):
    """
    Checks if a function is listed as a patchable function in the Register.
    """
    if instance:
        function_names_to_patch = Register.function_names_to_patch(instance)
    else:
        function_names_to_patch = Register.function_names_to_patch()

    return func_name in function_names_to_patch

def get_instance_from_args(args):
    # Check if there are any arguments
    if args:
        first_arg = args[0]

        # Check if the first argument is named "self" or "cls" (or any other specific name)
        if isinstance(first_arg, ast.Name) and first_arg.id in ("self", "cls"):
            instance = first_arg
            args = args[1:]  # Remove the first argument
        else:
            instance = None
    else:
        instance = None

    return instance, args

def register(func_name, *args, expected_output, positive=False, instance=None, **kwargs):
    if instance:
        function_names_to_patch = Register.function_names_to_patch(instance)  # , type=FunctionType.SYMBOLIC)
        functions_descriptions = [Register.load_function_description_from_name(instance, func_name)
                                  for func_name in function_names_to_patch]
    else:
        function_names_to_patch = Register.function_names_to_patch()  # type=FunctionType.SYMBOLIC)
        functions_descriptions = [Register.load_function_description_from_name(func_name)
                                  for func_name in function_names_to_patch]

    for desc, fn_name in zip(functions_descriptions, function_names_to_patch):
        if fn_name == func_name:
            hashed_description = desc.__hash__()
            if desc.type == FunctionType.EMBEDDABLE:
                if positive:
                    # Implement logic for handling positive (equality) assertions
                    positive_pairs = []
                    logger.log(ALIGN_LEVEL_NUM, f"Registering positive embedding pairs for {fn_name}: {positive_pairs}")
                    function_modeler.save_embeddable_align_statements(hashed_description, args, kwargs, positive_pairs=positive_pairs)
                else:
                    negative_pairs = []
                    logger.info(f"Registering negative embedding pairs for {fn_name}: {negative_pairs}")
                    function_modeler.save_embeddable_align_statements(hashed_description, args, kwargs, negative_pairs=negative_pairs)
            elif desc.type == FunctionType.SYMBOLIC:
                if positive:
                    logger.info(f"Registering symbolic align for {fn_name}{args}{dict(**kwargs)}: {expected_output}")
                    print(f"Registering symbolic align for {fn_name}{args}{dict(**kwargs)}: {expected_output}")
                    function_modeler.save_symbolic_align_statements(hashed_description, args, kwargs, expected_output)
                else:
                    raise NotImplementedError("Negative assertions for symbolic functions are not supported yet because most LLM providers dont offer a negative finetuning API")
            break

def make_dynamic_call_with_namespace(namespace):
    def dynamic_call(func_name, *args, __expected_output: any = None, __align_direction: bool = True, **kwargs):
        if 'self' in globals():
            # If 'self' is defined globally (unlikely in normal use),
            # this will throw an error as this approach relies on runtime context
            raise NameError("'self' found in globals; ambiguous context.")
        try:
            # Attempt to call as a method on an instance
            instance = kwargs.pop('instance', None)
            if instance is not None:
                method = getattr(instance, func_name)
                register(func_name, *args, **kwargs, positive=__align_direction, expected_output=__expected_output, instance=instance)
                return method(*args, **kwargs)
        except AttributeError:
            # 'instance' does not have the method; fall back to a function call
            pass

        _namespace = namespace
        # Possibly we should register the module of the function being called too.
        register(func_name, *args, **kwargs, positive=__align_direction, expected_output=__expected_output, instance=None)

    return dynamic_call

def dynamic_call(func_name, *args, __expected_output: any = None, __align_direction: bool = True, **kwargs):
    if 'self' in globals():
        # If 'self' is defined globally (unlikely in normal use),
        # this will throw an error as this approach relies on runtime context
        raise NameError("'self' found in globals; ambiguous context.")
    try:
        # Attempt to call as a method on an instance
        instance = kwargs.pop('instance', None)
        if instance is not None:
            method = getattr(instance, func_name)
            register(func_name, *args, **kwargs, positive=__align_direction, expected_output=__expected_output, instance=instance)
            return method(*args, **kwargs)
    except AttributeError:
        # 'instance' does not have the method; fall back to a function call
        pass

    _namespace = namespace
    # Possibly we should register the module of the function being called too.
    register(func_name, *args, **kwargs, positive=__align_direction, expected_output=__expected_output, instance=None)

def function_names_to_patch(*args, type: Optional[FunctionType] = None):
    """
    Get the registered function names that should be patched, either globally (if len(args)==0) or as members of
    an instance
    :param args: Optional instance to check
    :return:
    """
    function_names = []
    if len(args) == 1:
        instance = args[0]

        if type == FunctionType.SYMBOLIC:
            for key in alignable_symbolic_functions.keys():
                if hasattr(instance, key):
                    function_names.append(key)
            return function_names
        elif type == FunctionType.EMBEDDABLE:
            for key in alignable_embedding_functions.keys():
                if hasattr(instance, key):
                    function_names.append(key)
            return function_names
        else:
            for key in alignable_symbolic_functions.keys():
                if hasattr(instance, key):
                    function_names.append(key)
            for key in alignable_embedding_functions.keys():
                if hasattr(instance, key):
                    function_names.append(key)
            return function_names
    else:
        if type == FunctionType.SYMBOLIC:
            return list(alignable_symbolic_functions.keys())
        elif type == FunctionType.EMBEDDABLE:
            return list(alignable_embedding_functions.keys())
        else:
            return list(alignable_symbolic_functions.keys()) + list(alignable_embedding_functions.keys())

def functions_to_patch(*args, type: Optional[FunctionType] = None) -> Dict[str, Callable]:
    function_names = Register.function_names_to_patch(*args, type=type)
    if type == FunctionType.SYMBOLIC:
        return {key: alignable_symbolic_functions[key] for key in function_names}
    elif type == FunctionType.EMBEDDABLE:
        return {key: alignable_embedding_functions[key] for key in function_names}
    else:
        return {key: alignable_symbolic_functions[key] for key in function_names} + \
               {key: alignable_embedding_functions[key] for key in function_names}

def load_function_description_from_name(*args) -> FunctionDescription:
    """
    Load a function description from a function name from the global scope.
    :param func_name:
    :return:
    """
    if len(args) == 1:
        instance = None
        func_name = args[0]
    elif len(args) == 2:
        instance = args[0]
        func_name = args[1]
    else:
        raise ValueError("Invalid number of arguments")

    if not instance:
        if func_name in alignable_symbolic_functions:
            func_object = alignable_symbolic_functions[func_name]
        elif func_name in alignable_embedding_functions:
            func_object = alignable_embedding_functions[func_name]
    else:
        func_object = getattr(instance, func_name)

    return Register.load_function_description(func_object)

def _get_dataset_info(self, dataset_type, func_hash, type="length"):
    """
    Get the dataset size for a function hash
    """
    return self.data_worker.load_dataset(dataset_type, func_hash, return_type=type)

def save_symbolic_datapoint(self, func_hash, example):
    """
    Save datapoint to the training data
    """
    written_datapoints = self.data_worker.log_symbolic_patch(func_hash, example)
    for func_hash, datapoints in written_datapoints.items():
        if func_hash in self.dataset_sizes[PATCHES]:
            # if the dataset size is -1, it means we havent read in the dataset size yet
            if self.dataset_sizes[PATCHES][func_hash] == -1:
                self.dataset_sizes[PATCHES][func_hash] = self._get_dataset_info(PATCHES, func_hash, type="length")
            else:
                self.dataset_sizes[PATCHES][func_hash] += datapoints
        else:
            self.dataset_sizes[PATCHES][func_hash] = datapoints
    return len(written_datapoints) > 0

def postprocess_symbolic_datapoint(self, func_hash, function_description, example, repaired=True):
    """
    Postprocess the datapoint
    First check if the datapoint should be added to the training data
    Add the datapoint if it should be added
    Then check if the function should be finetuned and execute finetuning if it should
    """
    try:
        if func_hash not in self.store_data_blacklist:
            added = self.save_symbolic_datapoint(func_hash, example)
            if added:
                self._update_datapoint_config(repaired, func_hash)
    except Exception as e:
        print(e)
        print("Could not add datapoint to training data")
    if func_hash not in self.execute_finetune_blacklist:
        self.check_for_finetuning(function_description, func_hash)

def check_for_finetuning(self, function_description, func_hash):
    """
    Check for finetuning status
    If already finetuning, check for finetuning status
    If not finetuning, check for finetuning condition and execute finetuning if condition is met
    """
    try:
        # check if already finetuning
        if "job_id" in self.function_configs[func_hash].current_training_run:
            # check for job status
            self._check_finetuning_status(func_hash, function_description)
        else:
            # check for finetuning condition
            if self._check_finetuning_condition(func_hash, function_description):
                self._execute_finetuning(function_description, func_hash)
    except Exception as e:
        print(e)
        print("Error checking for finetuning")

def _configure_function_models(self, teacher_models: List[Union[str, BaseModelConfig]],
                               student_model: str,
                                func_hash: str,
                                task_type: str):
    """
    Configure the function models
    """
    if teacher_models:
        self._configure_teacher_models(teacher_models, func_hash, task_type)
    if student_model:
        self._configure_student_model(student_model, func_hash, task_type)

    if teacher_models and not student_model:
        for model_config in self.teacher_models_override[func_hash]:
            # ban all non-openai models from finetuning if teacher is not openai and student is not specified because it doesnt make sense 
            if model_config.provider != OPENAI_PROVIDER and func_hash not in self.check_finetune_blacklist:
                self.check_finetune_blacklist.append(func_hash)
            if model_config.provider != OPENAI_PROVIDER and func_hash not in self.execute_finetune_blacklist:
                self.execute_finetune_blacklist.append(func_hash)

def _configure_teacher_models(self,
                                teacher_models: List[Union[str, BaseModelConfig]],
                                func_hash: str,
                                task_type: str):
    """
    Add custom teacher models to the function config
    First this is added to the teacher_models_override dict, which is used to override the teacher models
    Args:
        teacher_models: A list of teacher models to use for the function hash
        func_hash: The function hash to add the teacher models to
    """
    if func_hash not in self.teacher_models_override:
            self.teacher_models_override[func_hash] = []
    if task_type == FunctionType.EMBEDDABLE:
        preconfigured_models = DEFAULT_EMBEDDING_MODELS
    elif task_type == FunctionType.SYMBOLIC:
        preconfigured_models = DEFAULT_TEACHER_MODELS
    for model in teacher_models:
        if isinstance(model, str):
            if model not in preconfigured_models:
                raise Exception(f"Teacher model {model} not supported by default. Please include it in the list in extended config format")
            model_config = preconfigured_models[model]
        elif isinstance(model, BaseModelConfig):
            model_config = model
        self.teacher_models_override[func_hash].append(model_config)

